function preprocess(fileName, code) {

    var classMatch = code.match(/class\s+(\S+)(?:\s+extends\s+(?:\S+))?/),
        parentMatch = code.match(/class\s+(?:\S+)(?:\s+extends\s+(\S+))?/),
