            } else if(loopModules) {

                if('buns' === splittedName[splittedName.length - 2]) {
                    newNamespace = 'var ' + splittedName[splittedName.length - 1] + ' = ' + splittedName[splittedName.length - 1] + ' || {};';
                } else {
