                                    output += '{"' + (matchKey ? matchKey[1] : 'mixed') + '": ' + matchVal[1] + '}';
                                    if((i + 1) !== args.length)
                                        output += ', ';
                                }
                            }
                            code = code.replace(val, val + `Development.Debugger.Argument.check([` + output + `], '` + funcName[1] + `', ` + explodedName + `);`);
                        }
                    }
                });
            }
        }
    }

    namespacify();
    if('dev' === config.mode)
        enableDebug();
    return code;
}


